export async function loadArt(){const result={};await Promise.all(Object.entries({maps:'rpg-maps.png',cast:'rpg-cast.png',muho:'kim-muho-sprites.png'}).map(async([key,file])=>{const img=new Image();img.src='assets/'+file;await img.decode();result[key]=img}));result.people=Array.from({length:6},(_,i)=>trim(result.cast,i*result.cast.width/6,0,result.cast.width/6,result.cast.height));result.frames=Array.from({length:4},(_,row)=>Array.from({length:4},(_,col)=>trim(result.muho,[120,380,635,890][col],[0,315,620,925][row],[260,255,255,260][col],[315,305,305,322][row])));return result}
function trim(img,sx,sy,sw,sh){sx=Math.floor(sx);sy=Math.floor(sy);sw=Math.floor(sw);sh=Math.floor(sh);const c=document.createElement('canvas');c.width=sw;c.height=sh;const g=c.getContext('2d');g.drawImage(img,sx,sy,sw,sh,0,0,sw,sh);const d=g.getImageData(0,0,sw,sh).data;let x0=sw,y0=sh,x1=0,y1=0;for(let y=0;y<sh;y++)for(let x=0;x<sw;x++)if(d[(y*sw+x)*4+3]>150){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}return [sx+x0,sy+y0,Math.max(1,x1-x0+1),Math.max(1,y1-y0+1)]}
export function person(g,art,p,time=0){const h=p.kind==='muho'?43:44;g.fillStyle='#11182755';g.beginPath();g.ellipse(p.x,p.y+1,13,4,0,0,Math.PI*2);g.fill();const bob=p.walk?Math.sin(time*13)*1.2:0;let box,img;if(p.kind==='muho'){box=art.frames[p.dir||0][p.walk?Math.floor(time*8)%4:1];img=art.muho}else{box=art.people[p.kind];img=art.cast}const w=box[2]/box[3]*h;g.drawImage(img,...box,Math.round(p.x-w/2),Math.round(p.y-h+bob),w,h);if(p.name)label(g,p.name,p.x,p.y-h-6,'#f1e7d0',10)}
export function label(g,text,x,y,color='#ffe39e',size=12){g.font=`bold ${size}px sans-serif`;g.textAlign='center';g.lineWidth=3;g.strokeStyle='#14162c';g.strokeText(text,x,y);g.fillStyle=color;g.fillText(text,x,y)}
export function ball(g,x,y){g.fillStyle='#0b162c66';g.fillRect(x-6,y+5,14,3);g.fillStyle='#e8ecdf';g.beginPath();g.moveTo(x-6,y-3);g.lineTo(x-2,y-7);g.lineTo(x+4,y-6);g.lineTo(x+8,y);g.lineTo(x+5,y+6);g.lineTo(x-4,y+7);g.lineTo(x-8,y+1);g.closePath();g.fill();g.fillStyle='#283445';g.fillRect(x-2,y-2,5,5);g.fillRect(x-6,y-4,3,2);g.fillRect(x+4,y+3,3,3)}
export function scene(g,art,map,t,turf=0){g.imageSmoothingEnabled=false;if(['classroom','corridor','mountain','factory'].includes(map)){const boxes={classroom:[0,0,765,487],corridor:[775,0,761,487],mountain:[0,498,765,526],factory:[775,498,761,526]};g.drawImage(art.maps,...boxes[map],0,0,800,520);if(map==='mountain'){rock(g,320,295,45,30);rock(g,415,365,50,25)}if(map==='factory'){for(let i=0;i<8;i++){g.fillStyle=Math.sin(t*5+i)>0?'#a7e8c2':'#35575a';g.fillRect(174+i*65,102,5,5)}}return}field(g,map==='dirt',t,turf,map==='stadium')}
function rock(g,x,y,w,h){g.fillStyle='#3f414b';g.fillRect(x+6,y,w-12,h);g.fillRect(x,y+8,w,h-13);g.fillStyle='#737982';g.fillRect(x+7,y+3,w-17,9);g.fillStyle='#939e9b';g.fillRect(x+10,y+2,12,4)}
function field(g,dirt,t,turf,stadium){g.fillStyle='#303f44';g.fillRect(0,0,800,520);g.fillStyle='#303142';g.fillRect(0,0,800,145);for(let row=0;row<5;row++){g.fillStyle=row%2?'#595265':'#444254';g.fillRect(25,20+row*23,750,18);for(let i=0;i<52;i++){g.fillStyle=['#d0b7ac','#d9c48c','#8aabc1','#bd7488'][((i*7+row*3)%4)];g.fillRect(34+i*14,24+row*23+Math.floor(Math.sin(t*2+i)*1.5),5,5);g.fillStyle=['#83696a','#3c7289','#81754a'][i%3];g.fillRect(32+i*14,29+row*23,9,8)}}g.fillStyle='#bd9566';g.fillRect(60,150,680,345);for(let y=160;y<490;y+=16)for(let x=70;x<730;x+=16){const green=!dirt||x<70+turf*660;g.fillStyle=green?((Math.floor(y/48)%2)?'#50784b':'#5a8552'):((x+y)%3?'#b38e61':'#b99b70');g.fillRect(x,y,16,16);g.fillStyle=green?'#6e9659':'#cfac7b';g.fillRect(x+(x*y%9),y+5,3,1)}g.strokeStyle='#d6dcb9';g.lineWidth=2;g.strokeRect(110,185,580,270);g.beginPath();g.moveTo(110,330);g.lineTo(690,330);g.stroke();g.beginPath();g.ellipse(400,330,55,37,0,0,Math.PI*2);g.stroke();g.strokeRect(300,185,200,65);g.fillStyle='#252b39';g.fillRect(350,150,100,35);g.strokeStyle='#f3ede1';g.lineWidth=3;g.strokeRect(350,150,100,35);g.lineWidth=1;for(let x=355;x<450;x+=9){g.beginPath();g.moveTo(x,150);g.lineTo(x,185);g.stroke()}for(let y=155;y<185;y+=8){g.beginPath();g.moveTo(350,y);g.lineTo(450,y);g.stroke()}label(g,stadium?'PRESTO CUP · FINAL':'YOUTH FOOTBALL CLUB',400,16,'#efe0b3',12)}
export function marker(g,task,p,t){if(!task)return;const {x,y}=task;g.save();g.setLineDash([4,8]);g.strokeStyle='#ffe19a77';g.lineWidth=1;g.beginPath();g.moveTo(p.x,p.y+5);g.lineTo(x,y);g.stroke();g.restore();g.strokeStyle='#ffe6a1';g.lineWidth=2;g.beginPath();g.ellipse(x,y+3,18+Math.sin(t*4)*2,7,0,0,Math.PI*2);g.stroke();label(g,'◆',x,y-52+Math.sin(t*4)*3,'#ffe49f',18);label(g,Math.hypot(p.x-x,p.y-y)<55?'Space / 행동키':'목표',x,y-69,'#fff4ca',10)}
